package vn.freshlink.delivery;
import java.math.BigDecimal;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import vn.freshlink.common.api.ApiResponse;import vn.freshlink.identity.Actor;
@RestController @RequestMapping("/api/trips") public class RouteOptimizationController{
 private final JdbcTemplate jdbc;public RouteOptimizationController(JdbcTemplate j){jdbc=j;}
 record Point(long id,double lat,double lon){}
 @PostMapping("/{id}/optimize") @Transactional public ApiResponse<?> optimize(@AuthenticationPrincipal Actor a,@PathVariable long id){a.requireRole("OPERATIONS_COORDINATOR");var trip=jdbc.queryForMap("SELECT * FROM delivery_trips WHERE trip_id=? FOR UPDATE",id);if(!Set.of("PLANNED","LOADING").contains(trip.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Chỉ tối ưu chuyến chưa bắt đầu");var origin=jdbc.queryForMap("SELECT latitude,longitude FROM addresses WHERE address_id=?",trip.get("origin_address_id"));if(origin.get("latitude")==null||origin.get("longitude")==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Điểm xuất phát chưa có tọa độ");var rows=jdbc.queryForList("SELECT s.trip_stop_id,a.latitude,a.longitude FROM trip_stops s JOIN addresses a ON a.address_id=s.delivery_address_id WHERE s.trip_id=? ORDER BY s.stop_sequence FOR UPDATE",id);if(rows.stream().anyMatch(x->x.get("latitude")==null||x.get("longitude")==null))throw new ResponseStatusException(HttpStatus.CONFLICT,"Một hoặc nhiều điểm giao chưa có tọa độ");var pending=new ArrayList<Point>();for(var x:rows)pending.add(new Point(((Number)x.get("trip_stop_id")).longValue(),((BigDecimal)x.get("latitude")).doubleValue(),((BigDecimal)x.get("longitude")).doubleValue()));double lat=((BigDecimal)origin.get("latitude")).doubleValue(),lon=((BigDecimal)origin.get("longitude")).doubleValue();var ordered=new ArrayList<Long>();while(!pending.isEmpty()){double aLat=lat,aLon=lon;var next=pending.stream().min(Comparator.comparingDouble(p->distance(aLat,aLon,p.lat(),p.lon()))).orElseThrow();ordered.add(next.id());lat=next.lat();lon=next.lon();pending.remove(next);}jdbc.update("UPDATE trip_stops SET stop_sequence=stop_sequence+1000 WHERE trip_id=?",id);for(int i=0;i<ordered.size();i++)jdbc.update("UPDATE trip_stops SET stop_sequence=? WHERE trip_id=? AND trip_stop_id=?",i+1,id,ordered.get(i));jdbc.update("UPDATE delivery_trips SET route_data=JSON_OBJECT('method','NEAREST_NEIGHBOR','optimizedAt',UTC_TIMESTAMP(3)) WHERE trip_id=?",id);return ApiResponse.success(Map.of("stopIds",ordered,"method","NEAREST_NEIGHBOR"),"Đã tối ưu thứ tự điểm giao");}
 private double distance(double a,double b,double c,double d){double x=Math.toRadians(d-b)*Math.cos(Math.toRadians((a+c)/2)),y=Math.toRadians(c-a);return Math.sqrt(x*x+y*y)*6371;}
}
